;(async()=>{
 const assert=require('node:assert/strict'),C=require('node:crypto'),F=require('node:fs'),P=require('node:path'),O=require('node:os'),{createHomeKick}=require('./server.cjs');
 const dir=F.mkdtempSync(P.join(O.tmpdir(),'kick-home-test-')),now=Date.now(),{publicKey,privateKey}=C.generateKeyPairSync('rsa',{modulusLength:2048});
