 try{assert.equal(await server.sync([{id:'test'},{id:'new'}]),30000);assert.equal(posts,1);await server.sync([{id:'test'},{id:'new'}]);assert.equal(posts,1);assert.equal(server.health().ready,true);assert.equal(server.health().chatConfirmed,1);
 const signed=(n,type,p,stamp=new Date(now).toISOString())=>{const raw=Buffer.from(JSON.stringify(p)),message=id(n),headers={'kick-event-type':type,'kick-event-version':'1','kick-event-subscription-id':id(kinds.indexOf(type)+1),'kick-event-message-id':message,'kick-event-message-timestamp':stamp,'kick-event-signature':C.sign('RSA-SHA256',Buffer.concat([Buffer.from(message+'.'+stamp+'.'),raw]),privateKey).toString('base64')};return {headers,raw};};
 const payload={broadcaster:{user_id:42},sender:{user_id:99},created_at:new Date(now-1000).toISOString(),content:'do not store this'};
 const send=(n,k,p)=>{const {headers,raw}=signed(n,k,p);return server.processEvent(headers,raw);};
 assert.equal(send(100,kinds[0],payload),204);assert.equal(send(100,kinds[0],payload),204);assert.equal(send(101,kinds[0],payload),204);assert.equal(send(102,kinds[0],{...payload,sender:{user_id:100}}),204);assert.equal(send(103,kinds[1],{...payload,gift:{amount:500}}),204);assert.equal(send(104,kinds[2],{...payload,giftees:[{},{}]}),204);
 let x=signed(105,kinds[0],payload);assert.equal(server.processEvent(x.headers,Buffer.from('{}')),403);assert.equal(send(106,kinds[0],{...payload,broadcaster:{user_id:43}}),400);x.headers['kick-event-subscription-id']=id(999);assert.equal(server.processEvent(x.headers,x.raw),503);
 const row={id:'test',startedAt:new Date(now-900000).toISOString()};server.apply(row);assert.equal(row.webhookChatReceived,3);assert.equal(row.webhookActiveReceived,2);assert.equal(row.kicksGift,500);assert.equal(row.giftedSubscriptionsReceived,2);assert.equal(row.giftedSubscriptions,3);assert.equal(server.health().received,5);const short={id:'test',startedAt:new Date(now-100).toISOString()};server.apply(short);assert.equal(short.webhookChatReceived,undefined);
 server.close();server=createHomeKick(options);await server.sync([{id:'test'},{id:'new'}]);const restored={id:'test',startedAt:row.startedAt};server.apply(restored);assert.equal(restored.webhookChatReceived,3);assert.equal(restored.kicksGift,500);assert.equal(send(100,kinds[0],payload),204);assert.equal(server.health().received,0);assert.equal(posts,1);console.log('25 home webhook signature, subscription, persistence and aggregate checks passed');
 }finally{server.close();F.rmSync(dir,{recursive:true,force:true});}
